class Solution {
public:
    vector<int> successfulPairs(vector<int>& spells, vector<int>& potions, long long success) {
        sort(potions.begin(), potions.end());
        int m = potions.size();
        vector<int> res;
        for (int i = 0; i < (int)spells.size(); i++) {
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if ((long long)spells[i] * potions[mid] >= success) hi = mid;
                else lo = mid + 1;
            }
            res.push_back(m - lo);
        }
        return res;
    }
};
